  1: using System;
  2: using System.Globalization;
  3: using System.Text;
  4: using SBR.Engine;
  5: using UnityEngine;
  6: using UnityEngine.UI;
  7: 
  8: namespace SBR.Game
  9: {
 10:     /// <summary>
 11:     /// The book, on the desk laptop (M4). A code-built world-space UGUI canvas on the lid showing
 12:     /// exactly one page dictated by the run phase (grill decision: the app railroads, no tabs):
 13:     /// BETSLIP during Betting (two-panel: slate rows left, working slip right, fraction-chip stakes,
 14:     /// LOCK IT IN with a zero-ticket confirm), GO WATCH while the round is locked, SHOP during Shop,
 15:     /// RUN OVER on RunWon/RunLost (NEW RUN is the prototype restart — a menu replaces it later).
 16:     /// A persistent header carries ROUND / BANK / TARGET / DEBT-in-red plus the relic strip.
 17:     ///
 18:     /// All engine mutations go through <see cref="RunDirector"/>/<see cref="BetslipModel"/>; the page
 19:     /// rebuilds when a state signature changes, so external flips (the TV settling the round) land
 20:     /// without wiring events. The lid breathes its emissive when the laptop wants attention.
 21:     /// Palette is law (design/08): green = money-good, red = money-bad, gold = payout moments.
 22:     /// </summary>
 23:     public sealed class LaptopScreen : MonoBehaviour
 24:     {
 25:         [Header("Wiring (set by GrayboxRoomBuilder)")]
 26:         public RunDirector director;
 27:         public Renderer lidRenderer; // the emissive lid quad behind the canvas
 28: 
 29:         [Header("Layout")]
 30:         public Vector2 screenWorldSize = new Vector2(0.32f, 0.22f);
 31:         [Tooltip("Metres the canvas floats in front of the lid (toward the room).")]
 32:         public float canvasOffset = 0.004f;
 33:         public int referencePixelsWide = 1024;
 34: 
 35:         [Header("Attention glow")]
 36:         [ColorUsage(false, true)] public Color idleEmission = new Color(0.025f, 0.055f, 0.035f);
 37:         [ColorUsage(false, true)] public Color attentionEmission = new Color(0.10f, 0.55f, 0.22f);
 38:         public float attentionBreathHz = 0.6f;
 39: 
 40:         [Header("Palette (design/08)")]
 41:         public Color screenBg = new Color(0.012f, 0.022f, 0.016f, 0.97f);
 42:         public Color panel = new Color(0.045f, 0.075f, 0.058f, 0.95f);
 43:         public Color panelHot = new Color(0.10f, 0.16f, 0.11f, 0.98f);
 44:         public Color chromeCyan = new Color(0.62f, 0.86f, 0.96f, 0.95f);
 45:         public Color textColor = new Color(0.90f, 0.95f, 0.98f, 1f);
 46:         public Color moneyGreen = new Color(0.25f, 0.95f, 0.45f, 1f);
 47:         public Color hotRed = new Color(0.95f, 0.25f, 0.22f, 1f);
 48:         public Color gold = new Color(0.98f, 0.78f, 0.25f, 1f);
 49: 
 50:         // ---- state ----
 51:         private Canvas _canvas;
 52:         private Font _font;
 53:         private RectTransform _header;
 54:         private RectTransform _pageBetslip, _pageShop, _pageRunOver, _pageLocked;
 55:         private Text _tHeaderLeft, _tHeaderRight;
 56: 
 57:         private BetslipModel _slip;
 58:         private int _slipRunGen = -1;
 59:         private string _sig;
 60:         private bool _lockArmed;
 61:         private string _shopError = "";
 62: 
 63:         private MaterialPropertyBlock _emissBlock;
 64:         private static readonly int EmissionColorId = Shader.PropertyToID("_EmissionColor");
 65: 
 66:         /// <summary>Test/debug surface: the model behind the betslip page.</summary>
 67:         public BetslipModel Slip => _slip;
 68: 
 69:         // =====================================================================================
 70: 
 71:         private void Awake()
 72:         {
 73:             _font = LoadFont();
 74:             _emissBlock = new MaterialPropertyBlock();
 75:             BuildSkeleton();
 76:         }
 77: 
 78:         private void Update()
 79:         {
 80:             if (director == null || director.Run == null) return;
 81: 
 82:             if (_canvas.worldCamera == null)
 83:                 _canvas.worldCamera = Camera.main;
 84: 
 85:             EnsureSlip();
 86: 
 87:             string sig = Signature();
 88:             if (sig != _sig)
 89:             {
 90:                 _sig = sig;
 91:                 Rebuild();
 92:             }
 93: 
 94:             Glow();
 95:         }
 96: 
 97:         private void EnsureSlip()
 98:         {
 99:             if (_slipRunGen == director.RunGeneration && _slip != null) return;
100:             _slip = new BetslipModel(director.Run);
101:             _slipRunGen = director.RunGeneration;
102:             _lockArmed = false;
103:             _shopError = "";
104:         }
105: 
106:         private string Signature()
107:         {
108:             Run r = director.Run;
109:             var sb = new StringBuilder(96);
110:             sb.Append(director.RunGeneration).Append('|').Append(r.Phase).Append('|').Append(r.Round)
111:               .Append('|').Append((long)r.Bank).Append('|').Append((long)(r.Comps * 10))
112:               .Append('|').Append((long)r.CurrentPayment) // the Marker moves it mid-phase
113:               .Append('|').Append(r.Tickets.Count).Append('|').Append(r.ShopOffers.Count)
114:               .Append('|').Append(r.ConsumableOffers.Count).Append('|').Append(r.OwnedRelics.Count)
115:               .Append('|').Append(r.OwnedConsumables.Count).Append('|').Append((long)(r.ScarStacks * 10))
116:               .Append('|').Append(_lockArmed).Append('|').Append(_shopError.Length)
117:               .Append('|').Append((long)(_slip?.Stake ?? 0)).Append('|').Append(_slip?.BoostLeg ?? -1)
118:               .Append('|').Append((int)(_slip?.Modifier ?? TicketModifier.None));
119:             foreach (EffectStat s in r.EffectStates)
120:                 sb.Append('|').Append((long)(s.Value * 10)); // ratchet/streak chrome (rev 5 §20)
121:             if (_slip != null)
122:                 foreach (Pick p in _slip.Picks)
123:                     sb.Append('|').Append(p.MatchupIndex).Append(p.Side == Side.Home ? 'H' : 'A');
124:             return sb.ToString();
125:         }
126: 
127:         // ------------------------------------------------------------------ page routing
128: 
129:         private void Rebuild()
130:         {
131:             Run r = director.Run;
132: 
133:             RebuildHeader(r);
134: 
135:             SetPage(_pageBetslip, r.Phase == Phase.Betting);
136:             SetPage(_pageLocked, r.Phase == Phase.Sweat || r.Phase == Phase.Settlement);
137:             SetPage(_pageShop, r.Phase == Phase.Shop);
138:             SetPage(_pageRunOver, r.Phase == Phase.RunWon || r.Phase == Phase.RunLost);
139: 
140:             if (r.Phase == Phase.Betting) RebuildBetslip(r);
141:             else if (r.Phase == Phase.Shop) RebuildShop(r);
142:             else if (r.Phase == Phase.RunWon || r.Phase == Phase.RunLost) RebuildRunOver(r);
143:             else RebuildLocked(r);
144:         }
145: 
146:         private static void SetPage(RectTransform page, bool active)
147:         {
148:             if (page.gameObject.activeSelf != active)
149:                 page.gameObject.SetActive(active);
150:         }
151: 
152:         private void RebuildHeader(Run r)
153:         {
154:             // The bank must HOLD the payment at settle — the header goes red when it doesn't.
155:             bool short_ = r.Bank < r.CurrentPayment;
156:             _tHeaderLeft.text =
157:                 $"ROUND {r.Round}/{r.Config.Rounds}   BANK {Money(r.Bank)}   PAYMENT DUE {Money(r.CurrentPayment)}"
158:                 + $"   COMPS {r.Comps.ToString("0.#", CultureInfo.InvariantCulture)}";
159:             _tHeaderLeft.color = short_ ? hotRed : chromeCyan;
160: 
161:             var right = new StringBuilder();
162:             if (r.ScarStacks > 0)
163:                 right.Append($"SCAR {r.ScarStacks.ToString("0.#", CultureInfo.InvariantCulture)}pp   ");
164:             foreach (EffectStat s in r.EffectStates)
165:             {
166:                 if (s.Value <= 0 || s.Id == RelicCatalog.ScarTissueId) continue; // scar shown above
167:                 right.Append(s.Id == "the_system"
168:                     ? $"{s.Label} x{s.Value.ToString("0", CultureInfo.InvariantCulture)}   "
169:                     : $"{s.Label} {s.Value.ToString("0.#", CultureInfo.InvariantCulture)}pp   ");
170:             }
171:             if (r.OwnedRelics.Count > 0)
172:             {
173:                 var names = new StringBuilder();
174:                 foreach (RelicDefinition d in r.OwnedRelics)
175:                 {
176:                     if (names.Length > 0) names.Append(" · ");
177:                     names.Append(d.Name.ToUpperInvariant());
178:                 }
179:                 right.Append(names);
180:             }
181:             right.Append($"   {r.OwnedRelics.Count}/{r.Config.RelicSlots}R {r.OwnedConsumables.Count}/{r.Config.ConsumableSlots}C");
182:             _tHeaderRight.text = right.ToString();
183:         }
