 301:         /// <summary>The locked round, serially: ticket card → sweat → per-ticket beat, for each ticket,
 302:         /// then FinishAndSettle and the settle card. The director owns the index; we own the ceremony.</summary>
 303:         private IEnumerator PresentRound()
 304:         {
 305:             _idleKey = null;
 306: 
 307:             while (director.Run.Phase == Phase.Sweat && director.CurrentSession != null)
 308:             {
 309:                 _session = director.CurrentSession;
 310:                 _ticket = director.CurrentTicket;
 311: 
 312:                 yield return TicketCardBeat();
 313:                 yield return PlaySweat();
 314:                 yield return SettlementBeat();
 315: 
 316:                 if (!director.AdvanceSweat()) break;
 317:             }
 318: 
 319:             if (director.Run.Phase == Phase.Sweat)
 320:             {
 321:                 director.FinishAndSettle();
 322:                 yield return SettleCardBeat();
 323:             }
 324:         }
