 326:         private IEnumerator TicketCardBeat()
 327:         {
 328:             ResetForNewSession(); // clears floods/dim/static, resets the light, shows the attract
 329:             _tAttract.text = "SIT TO WATCH THE SWEAT";
 330:             _tAttract.color = new Color(phosphorGreen.r, phosphorGreen.g, phosphorGreen.b, 1f);
 331:             RenderTicketCard();
