 338:         private IEnumerator PlaySweat()
 339:         {
 340:             RenderPregame();
 341:             int lastLeg = _ticket.Legs.Count - 1;
 342: 
 343:             while (_session != null && !_session.IsComplete)
 344:             {
 345:                 yield return WaitSeated();            // step ONLY while seated
 346:                 if (_session.IsComplete) break;      // e.g. cashed out while we waited
 347: 
 348:                 if (!_session.MoveNext(out DramaEvent evt)) break;
 349:                 _eventsEmitted++;
 350:                 RenderEvent(evt);
 351: 
 352:                 if (_stage != null)
 353:                 {
 354:                     // M-T3: the scenes own pacing AND the resolution ceremony.
 355:                     yield return TheaterBeat(evt);
 356:                     continue;
 357:                 }
 358: 
 359:                 bool onFinalLeg = evt.LegIndex == lastLeg;
 360:                 if (evt.Type == DramaEventType.LegFinal)
 361:                     yield return ResolveBeat(evt);
 362: 
 363:                 // The pending-loss window (charm expansion): a dead leg suspended the session
 364:                 // while a save is held — the drama freezes on the player's timed decision.
 365:                 if (_session.HasPendingLoss)
 366:                     yield return PendingWindowBeat();
 367: 
 368:                 if (_session.IsComplete) break;
 369:                 yield return SeatedHold(PacingFor(evt, onFinalLeg));
 370:             }
 371:         }
