 467:         /// <summary>Waits out the active scene. Seating freezes the stage (the scene stalls, so
 468:         /// this stalls with it); a cash-out abandons the scene — the gold flood takes the screen.</summary>
 469:         private IEnumerator WaitSceneDone()
 470:         {
 471:             while (_stage != null && _stage.ScenePlaying)
 472:             {
 473:                 if (_ticket != null && _ticket.State == TicketState.CashedOut)
 474:                 {
 475:                     _stage.CancelScene();
 476:                     yield break;
 477:                 }
 478:                 yield return null;
 479:             }
 480:         }
