 482:         /// <summary>The GREEN/DEAD slam, fired as the final scene completes (TvLight sync) —
 483:         /// which is also the final's REVEAL moment: only now do the clock read FT and the bar
 484:         /// snap to the outcome. The VOID path already spoke inside the pending window (the
 485:         /// slip ceremony), and a voided match keeps its pre-kill bar — 0/1 never applied.</summary>
 486:         private IEnumerator FinalSlam(DramaEvent evt, LegGrade grade)
 487:         {
 488:             _tClock.text = "FT";
 489:             _finalSequenceActive = false;
 490:             _clockTicking = false;
 491:             if (grade == LegGrade.Won)
 492:             {
 493:                 _probTarget = 1f;
 494:                 _tWinPct.text = "WIN 100%";
 495:             }
 496:             else if (grade == LegGrade.Lost)
 497:             {
 498:                 _probTarget = 0f;
 499:                 _tWinPct.text = "WIN 0%";
 500:             }
 501: 
 502:             _resolvedThrough = evt.LegIndex + 1;
 503:             UpdateSlipStrip(evt.LegIndex + 1);
 504:             _tape?.ResolveLeg(evt.LegIndex, grade);
 505:             PunchWinProbBar();
 506:             int k = evt.LegIndex + 1;
 507:             if (grade == LegGrade.Won)
 508:             {
 509:                 _audio?.Whistle();
 510:                 _audio?.SlamWon();
 511:                 yield return GreenLegBeat(k);
 512:             }
 513:             else if (grade == LegGrade.Lost)
 514:             {
 515:                 _audio?.Whistle();
 516:                 _audio?.SlamLost();
 517:                 yield return DeadLegBeat(k);
 518:             }
 519:             _audioUrgency = 0f;
 520:             ReopenMarket(); // between legs (or at the end) the fresh price may speak again
 521:         }
