 523:         /// <summary>A staged goal's playback completed: the ledger commits (or the chalk-off
 524:         /// stands), the scorebug speaks, VAR gets its line. The ONLY score path (goal-playback
 525:         /// invariant: the board can never move without a goal on the pitch).</summary>
 526:         private void OnGoalPlayed(ScoreLedger.StagedGoal goal)
 527:         {
 528:             _audio?.GoalHit(goal.Commits);
 529:             _ledger.CompleteGoal(goal);
 530:             if (_finalSequenceActive)
 531:             {
 532:                 _stoppageGoalCount++;
 533:                 _tClock.text = $"90'+{_stoppageGoalCount}";
 534:             }
 535:             if (_ticket != null && _stageLeg >= 0 && _stageLeg < _ticket.Legs.Count)
 536:                 UpdateScorebug(_ticket.Legs[_stageLeg]);
 537:             if (!goal.Commits)
 538:             {
 539:                 _tFlavor.color = flavorColor;
 540:                 _tFlavor.text = "VAR — NO GOAL";
 541:                 _flavorScale = 1.12f;
 542:             }
 543:         }
