 763:             string away = SweatFlavor.Short(leg.Matchup.Away.Name).ToUpperInvariant();
 764:             string home = SweatFlavor.Short(leg.Matchup.Home.Name).ToUpperInvariant();
 765:             string awayMark = leg.Side == Side.Away ? "● " : "";
 766:             string homeMark = leg.Side == Side.Home ? " ●" : "";
 767:             _tMatchup.text =
 768:                 $"<color=#{awayRgb:X6}>{awayMark}{away}</color>  {awayScore} — {homeScore}  " +
 769:                 $"<color=#{homeRgb:X6}>{home}{homeMark}</color>";
 770:         }
