375:         /// <summary>One beat as theater: non-final beats play their resolved scene (the scene's
376:         /// duration IS the pacing); a LegFinal plays the final whistle sequence with the
377:         /// ledger's stoppage-time plan; a pending loss suspends the kill scene at the shot
378:         /// mid-flight, holds through the save window, and resumes with the continuation chosen
379:         /// from the FINAL ticket-local grade (never WinProbAfter).</summary>
380:         private IEnumerator TheaterBeat(DramaEvent evt)
381:         {
382:             Leg leg = _ticket.Legs[evt.LegIndex];
383:             _stage.timeScale = Mathf.Max(0f, TimeScaleOverride);
384: 
385:             if (evt.Type != DramaEventType.LegFinal)
386:             {
387:                 SceneSpec spec = _choreo.ResolveBeat(evt, _lastBeatUp, _lastBeatDelta, _ledger);
388:                 bool nearMiss = spec.Template == SceneTemplate.NearMissHope
389:                     || spec.Template == SceneTemplate.NearMissScare;
390:                 _audioUrgency = spec.Urgent ? 1f : 0f;
391:                 if (nearMiss)
392:                 {
393:                     float riserSeconds = spec.Duration * 0.66f
394:                         * Mathf.Max(0.0001f, TimeScaleOverride);
395:                     _audio?.NearMissRiser(riserSeconds);
396:                 }
397:                 StartClockRun(SweatFlavor.Minute(evt), spec.Duration);
398: 
399:                 // A staged goal owns the beat's story (Sol, M-T4.1): the flavor speaks the
400:                 // goal call and the TAPE dot wears the SCORER'S color — both keyed to the
401:                 // goal's beneficiary, never the tie-broken beat direction (a flat floor
402:                 // beat reconciles for the opponent while the tie-break says "up").
403:                 if (spec.Goal.HasValue)
404:                 {
405:                     _pendingBeatBeneficiary = TeamColor(leg, spec.Goal.Value.ForPicked);
406:                     if (evt.Type == DramaEventType.Momentum)
407:                         _pendingFlavor = SweatFlavor.GoalLine(spec.Goal.Value.ForPicked, leg, evt.Step);
408:                 }
409: 
410:                 // Market suspension is for DANGEROUS scenes only (playtest #13 — blanket
411:                 // suspension left almost no window to cash out): goal chances and near-misses
412:                 // suspend until their reveal, exactly like a real book on a dangerous attack;
413:                 // possession scenes carry so little information that the market drifts openly
414:                 // — their chrome reveals at scene start.
415:                 bool dangerous = spec.Goal.HasValue
416:                     || spec.Template == SceneTemplate.NearMissHope
417:                     || spec.Template == SceneTemplate.NearMissScare;
418:                 if (dangerous)
419:                 {
420:                     SuspendMarket();
421:                     _stage.PlayScene(spec, OnGoalPlayed,
422:                         nearMiss ? RevealBeatAudio : RevealBeatChrome, null);
423:                 }
424:                 else
425:                 {
426:                     RevealBeatChrome(); // low-information beat: prob drifts, price stays live
427:                     _stage.PlayScene(spec, OnGoalPlayed, null, null);
428:                 }
429:                 yield return WaitSceneDone();
430:                 _audioUrgency = 0f;
431:                 if (_session.IsComplete) yield break; // cashed out mid-scene
432:                 yield return SeatedHold(interSceneGapMs); // idle filler ≤1s between scenes
433:                 yield break;
434:             }
435: 
436:             _audioUrgency = 1f;
437:             SuspendMarket(); // a final is always a dangerous attack
438:             BeginFinalSequenceClock();
439:             if (_session.HasPendingLoss)
440:             {
441:                 // The clippable moment: buildup → the shot freezes mid-flight → the prompt.
442:                 // The chrome still speaks the PRE-KILL state (the honest displayed value the
443:                 // whistle rolls against) — the 0% never shows before the story resolves.
444:                 _stage.SuspendKillShot(ScenePlaybook.VariantFor(evt.Step));
445:                 while (_stage.ScenePlaying && !_stage.SuspendedAtShot) yield return null;
446:                 yield return PendingWindowBeat();
447: 
448:                 LegGrade grade = leg.IsVoided ? LegGrade.Voided
449:                     : leg.GradesWon ? LegGrade.Won : LegGrade.Lost;
450:                 ScoreLedger.FinalPlan plan = _ledger.PlanFinal(grade);
451:                 _stage.ResumeSuspended(plan, OnGoalPlayed, null);
452:                 yield return WaitSceneDone();
453:                 yield return FinalSlam(evt, grade);
454:             }
455:             else
456:             {
457:                 LegGrade grade = leg.IsVoided ? LegGrade.Voided
458:                     : leg.GradesWon ? LegGrade.Won : LegGrade.Lost;
459:                 ScoreLedger.FinalPlan plan = _ledger.PlanFinal(grade);
460:                 SceneSpec spec = _choreo.ResolveFinal(grade, evt.Step);
461:                 _stage.PlayFinalScene(spec, plan, OnGoalPlayed, null);
462:                 yield return WaitSceneDone();
463:                 yield return FinalSlam(evt, grade);
464:             }
465:         }
