362:         // Terminal-realization ledger: every Lost Free Bet ticket refunds its stake, once.
363:         // The loss still happened everywhere it matters (scar fed, jar counts it).
364:         foreach (Ticket ticket in _tickets)
365:         {
366:             if (ticket.State == TicketState.Lost
367:                 && ticket.Modifier == TicketModifier.FreeBet
368:                 && !ticket.Refunded)
369:             {
