392:     /// <summary>
393:     /// The payment settle (design/10): the round's payment is DEDUCTED. Meet it and the run
394:     /// advances (final round → RunWon). Miss it and the run is over — unless the Totem of Undying
395:     /// has a charge and this is not the final payment: the whole payment is DEFERRED (the bank is
396:     /// untouched — working capital survives, playtest #8) and the NEXT payment grows by
397:     /// payment × (1 + juice). The final payment is never deferrable ("no next favor").
398:     /// </summary>
399:     public void Settle()
400:     {
401:         RequirePhase(Phase.Settlement);
402:         bool finalRound = Round == Config.Rounds;
403:         // The EFFECTIVE payment: base schedule × the live payment factor (House Key). The base
404:         // array is never factor-mutated — getters own the view (PLAN.md rev 5 §9).
405:         double payment = _payments[Round - 1] * _effects.PaymentFactor;
406:         double bankBefore = Bank;
407:         double shortfall = 0;
408:         bool totemFired = false;
409: 
410:         // RoundResolution fires BEFORE the payment (after the refund ledger): The System and
411:         // the Bad Beat Jar read the round as played, not as taxed.
412:         double roundPnl = bankBefore - _bankAtBettingStart;
413:         int won = 0, lost = 0, cashed = 0;
414:         double refunds = 0;
415:         foreach (Ticket t in _tickets)
416:         {
417:             if (t.State == TicketState.Won) won++;
418:             else if (t.State == TicketState.Lost) lost++;
419:             else if (t.State == TicketState.CashedOut) cashed++;
420:             if (t.Refunded) refunds += t.Stake;
421:         }
422:         _effects.OnRoundResolved(new RoundResolution(
423:             Round, roundPnl, _tickets.Count, won, lost, cashed, refunds));
424: 
425:         if (Bank >= payment)
426:         {
427:             Bank -= payment;
428:             Phase = finalRound ? Phase.RunWon : Phase.Shop;
429:         }
430:         else if (!finalRound && _effects.TryConsumeTotem())
431:         {
432:             // Playtest #8: the totem DEFERS the whole payment — bank untouched, and the payment
433:             // plus juice lands on the next one. The surcharge books at BASE rates (Codex r2 #3):
434:             // the House Key factor applies once, through the getters, never compounded in.
435:             shortfall = payment - Bank;
436:             _payments[Round] += _payments[Round - 1] * (1.0 + Config.TotemJuiceRate);
437:             totemFired = true;
438:             Phase = Phase.Shop;
439:         }
440:         else
441:         {
442:             shortfall = payment - Bank;
443:             Phase = Phase.RunLost;
444:         }
445: 
446:         LastSettlement = new SettlementReport(Round, payment, bankBefore, Bank, shortfall, totemFired, Phase);
447: 
448:         _consecutiveLosingRounds = roundPnl < 0 ? _consecutiveLosingRounds + 1 : 0;
449: 
450:         if (Phase == Phase.Shop)
