252:     /// gold (cash-out), cyan (VOID). Assignment is deterministic from the team NAME
253:     /// (FNV-1a, presentation-local — a team keeps its color across rounds and replays,
254:     /// no engine RNG involved); the away team takes the next distinct pool entry.
255:     /// </summary>
256:     public static class TheaterPalette
257:     {
258:         /// <summary>0xRRGGBB. Electric blue, magenta, orange, violet, broadcast white.</summary>
259:         public static readonly uint[] TeamPool = { 0x3D7BFF, 0xE84DD0, 0xFF8A2B, 0x9B5CF6, 0xF0F3F6 };
260: 
261:         public static (uint Home, uint Away) TeamColors(string homeName, string awayName)
262:         {
263:             int home = (int)(Fnv1a(homeName ?? string.Empty) % (uint)TeamPool.Length);
264:             int away = (int)(Fnv1a(awayName ?? string.Empty) % (uint)TeamPool.Length);
265:             if (away == home) away = (away + 1) % TeamPool.Length;
266:             return (TeamPool[home], TeamPool[away]);
267:         }
268: 
269:         private static uint Fnv1a(string s)
270:         {
271:             unchecked
272:             {
273:                 uint h = 2166136261;
274:                 for (int i = 0; i < s.Length; i++)
275:                 {
276:                     h ^= s[i];
277:                     h *= 16777619;
278:                 }
279:                 return h;
280:             }
281:         }
282:     }
283: }

