351:         private static void BuildLaptop(Materials mats, int layer, RunDirector director)
352:         {
353:             var root = new GameObject("Laptop");
354:             root.transform.position = new Vector3(1.15f, 0.85f, 1.62f);
355: 
356:             GameObject lapBase = Box("LaptopBase", root.transform,
357:                 new Vector3(1.08f, 0.76f, 1.62f), new Vector3(0.22f, 0.02f, 0.32f), mats.Bezel);
358: 
359:             // Lid: 0.32 x 0.22 quad hinged on the wall-side edge of the base, tilted 20
360:             // degrees back toward the wall (+X), screen facing the room (-X and up).
361:             const float lidTiltDeg = 20f;
362:             Vector3 hinge = new Vector3(1.19f, 0.77f, 1.62f);
363:             Vector3 widthDir = Vector3.forward; // hinge axis runs along Z
364:             Vector3 lidUp = Quaternion.AngleAxis(-lidTiltDeg, Vector3.forward) * Vector3.up;
365:             Vector3 lidNormal = Vector3.Cross(widthDir, lidUp); // -X and slightly up
366:             Vector3 lidCenter = hinge + lidUp * 0.11f;
367:             GameObject lid = Quad("LaptopScreen", root.transform, lidCenter,
368:                 new Vector2(0.32f, 0.22f), lidNormal, lidUp, mats.LaptopScreen);
369: 
370:             // Generous interaction volume - the laptop itself is too small to raycast comfortably.
371:             var grabVolume = root.AddComponent<BoxCollider>();
372:             grabVolume.center = Vector3.zero;
373:             grabVolume.size = new Vector3(0.45f, 0.4f, 0.5f);
374:             grabVolume.isTrigger = true;
375: 
376:             // M4: the laptop IS the book. DeskFocus glides the camera to the lid and frees the cursor;
377:             // LaptopScreen hangs the phase-driven pages (betslip/shop/run-over) on a world-space canvas.
378:             var focus = root.AddComponent<DeskFocus>();
379:             focus.highlightRenderers = new[] { lapBase.GetComponent<Renderer>() };
380: 
381:             // Focus anchor: in front of the lid along its outward normal, looking at its center.
382:             // The Quad primitive's visible face is local -Z, so outward = -lid.forward.
383:             Transform lidT = lid.transform;
384:             Vector3 outward = -lidT.forward;
385:             var anchor = new GameObject("FocusAnchor").transform;
386:             anchor.SetParent(root.transform, false);
387:             anchor.SetPositionAndRotation(
388:                 lidT.position + outward * LaptopFocusDistance,
389:                 Quaternion.LookRotation(-outward, lidT.up));
390:             focus.focusAnchor = anchor;
391: 
392:             var book = root.AddComponent<LaptopScreen>();
393:             book.director = director;
394:             book.lidRenderer = lid.GetComponent<Renderer>();
395: 
396:             SetLayerRecursive(root, layer);
397:         }
