 496:     /// <summary>The single resale truth (PLAN.md rev 5 §10): Bobblehead's 3× override rides its
 497:     /// resaleMult param; a fired (spent) Totem is worth 0; everything else sells at the global
 498:     /// SellBackFraction of list.</summary>
 499:     public double GetResaleValue(RelicDefinition def)
 500:     {
 501:         if (_effects.TotemSpent(def)) return 0.0;
