281:     private double RawCashOutFair()
282:     {
283:         double resolvedOddsProduct = 1.0;
284:         for (int j = 0; j < _currentLeg; j++)
285:             if (!_ticket.Legs[j].IsVoided)
286:                 resolvedOddsProduct *= _ticket.Legs[j].OfferedOdds;
287: 
288:         var remaining = new List<(double p, double o)>(_ticket.Legs.Count - _currentLeg);
289:         remaining.Add((_liveProb, _ticket.Legs[_currentLeg].OfferedOdds));
290:         for (int j = _currentLeg + 1; j < _ticket.Legs.Count; j++)
291:             if (!_ticket.Legs[j].IsVoided)
292:                 remaining.Add((_ticket.Legs[j].TrueProb, _ticket.Legs[j].OfferedOdds));
293: 
294:         double winSide = OddsMath.CashOutFair(_ticket.Stake, resolvedOddsProduct, remaining)
295:             * _ticket.PayoutMultiplier;
296: 
297:         if (_ticket.Modifier == TicketModifier.FreeBet && !_ticket.Refunded)
298:         {
299:             double pAll = 1.0;
300:             foreach ((double p, double _) in remaining) pAll *= p;
301:             winSide += (1.0 - pAll) * _ticket.Stake; // the loss-side refund is contract too
302:         }
