 109:         internal void ResolveLeg(int legIndex, LegGrade grade)
 110:         {
 111:             RevealedTicket ticket = CurrentTicket;
 112:             if (ticket == null || legIndex < 0 || legIndex >= ticket.Legs.Count) return;
 113:             ticket.Legs[legIndex].State = grade == LegGrade.Won ? RevealedLegState.Won
 114:                 : grade == LegGrade.Lost ? RevealedLegState.Lost : RevealedLegState.Voided;
 115:             if (grade == LegGrade.Lost) ticket.State = RevealedTicketState.Lost;
 116:             else
 117:             {
 118:                 bool allResolved = true;
 119:                 for (int i = 0; i < ticket.Legs.Count; i++)
 120:                     if (ticket.Legs[i].State == RevealedLegState.Pending || ticket.Legs[i].State == RevealedLegState.Live)
 121:                         allResolved = false;
 122:                 if (allResolved) ticket.State = RevealedTicketState.Won;
 123:             }
 124:             Revision++;
 125:         }
