 62:         public void Tick(Run run, BetslipModel slip)
 63:         {
 64:             if (_toast != null && Time.unscaledTime > _toastUntil)
 65:             {
 66:                 _toast = null;
 67:                 _signature = null;
 68:             }
 69:             if (!_hasPhase || run.Phase != _lastPhase)
 70:             {
 71:                 _lastPhase = run.Phase;
 72:                 _hasPhase = true;
 73:                 ApplyPhaseDefault(run.Phase);
 74:                 Invalidate();
 75:             }
 76: 
 77:             string viewRevision = _host.tv != null && _host.tv.RevealedView != null
 78:                 ? _host.tv.RevealedView.Revision.ToString(CultureInfo.InvariantCulture) : "-";
 79:             string signature = string.Concat(
 80:                 _host.director.RunGeneration, "|", run.Phase, "|", run.Round, "|",
 81:                 ((long)run.Bank).ToString(CultureInfo.InvariantCulture), "|", run.Tickets.Count, "|",
 82:                 run.ShopOffers.Count, "|", run.ConsumableOffers.Count, "|", run.OwnedRelics.Count, "|",
 83:                 run.OwnedConsumables.Count, "|", slip.Picks.Count, "|", ((long)slip.Stake).ToString(CultureInfo.InvariantCulture), "|",
 84:                 (int)slip.Modifier, "|", slip.BoostLeg, "|", _activeApp, "|", _tab, "|", viewRevision,
 85:                 "|", _toast);
 86:             if (signature == _signature) return;
 87:             _signature = signature;
 88:             Rebuild(run, slip);
 89:         }
