174:             for (int i = 0; i < slip.Picks.Count; i++)
175:             {
176:                 Pick pick = slip.Picks[i];
177:                 Matchup matchup = run.CurrentSlate.Matchups[pick.MatchupIndex];
178:                 Team team = pick.Side == Side.Home ? matchup.Home : matchup.Away;
179:                 LaptopUi.MakeText(panel, "Leg" + i, new Vector2(0f, 1f), new Vector2(0f, 1f),
180:                     new Vector2(14f, y), new Vector2(238f, 24f), 12, TextAnchor.UpperLeft, LaptopOs.White,

180:                     new Vector2(14f, y), new Vector2(238f, 24f), 12, TextAnchor.UpperLeft, LaptopOs.White,
181:                     $"{i + 1}. {LaptopUi.TeamShort(team)}   {OddsFormat.American(matchup.Odds(pick.Side))}", _font);
182:                 int matchupIndex = pick.MatchupIndex;
183:                 if (run.OwnsConsumable("profit_boost"))
184:                 {
185:                     bool boosted = slip.BoostLeg == i;
186:                     int legIndex = i;
187:                     LaptopUi.MakeButton(panel, "Boost" + i, boosted ? "BOOST ✓" : "BOOST",
188:                         new Vector2(1f, 1f), new Vector2(1f, 1f), new Vector2(-76f, y + 8f),
189:                         new Vector2(58f, 24f), 9, boosted ? LaptopOs.MoneyGold : LaptopOs.SurfaceRaised,
190:                         LaptopOs.White, () => { slip.ToggleBoost(legIndex); _invalidate(); }, _font);
191:                 }
192:                 LaptopUi.MakeButton(panel, "Remove" + i, "×", new Vector2(1f, 1f), new Vector2(1f, 1f),
193:                     new Vector2(-12f, y + 8f), new Vector2(25f, 24f), 16, LaptopOs.SurfaceRaised, LaptopOs.MoneyBad,
194:                     () => { slip.Remove(matchupIndex); _lockArmed = false; _invalidate(); }, _font);
195:                 y -= 27f;
196:             }
197: 
198:             y -= 4f;
199:             LaptopUi.MakeText(panel, "Combined", new Vector2(0f, 1f), new Vector2(0f, 1f),
200:                 new Vector2(14f, y), new Vector2(300f, 22f), 12, TextAnchor.UpperLeft, LaptopOs.Muted,
201:                 slip.Picks.Count > 0 ? $"COMBINED {OddsFormat.American(slip.CombinedOdds)}" : "COMBINED —", _font);
202:             y -= 28f;
203: 
204:             bool freeHeld = run.OwnsConsumable("free_bet");
205:             bool donHeld = run.OwnsConsumable("double_or_nothing");
206:             if (freeHeld || donHeld)
207:             {
208:                 if (freeHeld)
209:                     MakeModifier(panel, "FREE BET", TicketModifier.FreeBet, slip, 14f, y);
210:                 if (donHeld)
211:                     MakeModifier(panel, "DOUBLE OR NOTHING", TicketModifier.DoubleOrNothing, slip,
212:                         freeHeld ? 148f : 14f, y);
213:                 y -= 34f;
214:             }
215: 
216:             float chipX = 14f;
217:             MakeChip(panel, "10%", chipX, y, () => slip.SetStakeFraction(0.10)); chipX += 62f;
218:             MakeChip(panel, "25%", chipX, y, () => slip.SetStakeFraction(0.25)); chipX += 62f;
219:             MakeChip(panel, "50%", chipX, y, () => slip.SetStakeFraction(0.50)); chipX += 62f;
220:             MakeChip(panel, "MAX", chipX, y, () => slip.SetStakeFraction(1.00));
221:             y -= 34f;
222:             MakeChip(panel, "−$10", 14f, y, () => slip.Nudge(-10), 70f);
223:             MakeChip(panel, "+$10", 90f, y, () => slip.Nudge(10), 70f);
224:             y -= 32f;
225:             LaptopUi.MakeText(panel, "Stake", new Vector2(0f, 1f), new Vector2(0f, 1f),
226:                 new Vector2(14f, y), new Vector2(300f, 24f), 15, TextAnchor.UpperLeft, LaptopOs.White,
227:                 $"STAKE {LaptopUi.Money(slip.Stake)}   →   TO WIN {LaptopUi.Money(slip.ToWin)}", _font);
228:             y -= 32f;
229: 
230:             string blocker = slip.PlaceBlocker;
231:             LaptopUi.MakeButton(panel, "Place", blocker == null ? "PLACE TICKET" : blocker.ToUpperInvariant(),
232:                 new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(14f, y), new Vector2(302f, 34f), 12,
233:                 blocker == null ? LaptopOs.SurfaceRaised : LaptopOs.Surface,
234:                 blocker == null ? LaptopOs.MoneyGood : LaptopUi.Dim(LaptopOs.Muted),
235:                 blocker == null ? () => { slip.Place(); _lockArmed = false; _invalidate(); } : null, _font,
236:                 blocker == null && !boardFrozen);
237: 
238:             string lockLabel = boardFrozen ? "THE ROUND IS LOCKED" : run.Tickets.Count > 0 ? "LOCK IT IN" :
239:                 _lockArmed ? "NO BETS — SURE?" : "LOCK IT IN (NO BETS)";
240:             bool canLock = !boardFrozen;
241:             LaptopUi.MakeButton(panel, "Lock", lockLabel, new Vector2(0f, 0f), new Vector2(0f, 0f),
242:                 new Vector2(14f, 12f), new Vector2(302f, 40f), 15,
243:                 _lockArmed ? LaptopOs.MoneyBad : LaptopOs.Accent,
244:                 LaptopOs.White,
245:                 canLock ? () =>
246:                 {
247:                     if (run.Tickets.Count == 0 && !_lockArmed) { _lockArmed = true; _invalidate(); return; }
248:                     _lockArmed = false;
249:                     _host.director.LockRound();
250:                     _invalidate();
251:                 } : null, _font, canLock);
