310:                 ? "DEAD" : ticket.State == RevealedTicketState.CashedOut ? "CASHED OUT" : "RIDING";
311:             Color stateColor = ticket.State == RevealedTicketState.Won ? LaptopOs.MoneyGood
312:                 : ticket.State == RevealedTicketState.Lost ? LaptopOs.MoneyBad
