316:                 $"TICKET {ticket.Index + 1}   ·   {state}   ·   {LaptopUi.Money(ticket.Stake)} → {LaptopUi.Money(ticket.PotentialPayout)}", _font);
317:             string legs = string.Empty;
318:             for (int i = 0; i < ticket.Legs.Count; i++)
