323:                     : leg.State == RevealedLegState.Voided ? " VOID" : leg.State == RevealedLegState.Live ? " LIVE" : "";
324:                 legs += $"{leg.TeamName} {leg.AmericanOdds}{suffix}";
325:             }
326:             LaptopUi.MakeText(card, "Legs", new Vector2(0f, 1f), new Vector2(0f, 1f),
327:                 new Vector2(14f, -40f), new Vector2(425f, 50f), 12, TextAnchor.UpperLeft, LaptopOs.White, legs, _font);
328:         }
