466:                 new Vector2(24f, -38f), new Vector2(600f, 34f), 22, TextAnchor.UpperLeft, LaptopOs.White,
467:                 "Old Slips", _font);
468:             LaptopUi.MakeText(_root, "Sub", new Vector2(0f, 1f), new Vector2(0f, 1f),
469:                 new Vector2(25f, -70f), new Vector2(800f, 22f), 11, TextAnchor.UpperLeft, LaptopOs.Muted,
470:                 "the run's settled tickets, preserved for absolutely no reason", _font);
471: 
472:             int row = 0;
