480:                     : ticket.State == TicketState.CashedOut ? LaptopOs.MoneyGold : LaptopOs.MoneyBad;
481:                 LaptopUi.MakeText(_root, "Slip" + i, new Vector2(0f, 1f), new Vector2(0f, 1f),
482:                     new Vector2(26f, -126f - row * 42f), new Vector2(900f, 30f), 14, TextAnchor.UpperLeft,
483:                     stateColor, $"#{i + 1}   {ticket.State.ToString().ToUpperInvariant()}   ·   STAKE {LaptopUi.Money(ticket.Stake)}   ·   PAYOUT {payout}", _font);
